const p = msg.payload;
const errors = [];
if (!p || typeof p !== 'object') errors.push('invalid JSON object');
if (!p.device_id) errors.push('missing device_id');
if (!p.device_type) errors.push('missing device_type');
if (!p.timestamp) errors.push('missing timestamp');
if (p.sequence === undefined || p.sequence === null) errors.push('missing sequence');
if (p.value === undefined) errors.push('missing value');
if (p.timestamp && !String(p.timestamp).endsWith('Z')) errors.push('timestamp must be UTC ISO8601 ending with Z');
if (typeof p.sequence === 'number' && p.sequence < 0) errors.push('sequence must be non-negative');

if (errors.length > 0) {
  msg.payload = {
    event_type: 'SCHEMA_VALIDATION_FAILURE',
    severity: 'MEDIUM',
    risk_score: 10,
    description: errors.join('; '),
    device_id: (p && p.device_id) || 'unknown',
    mqtt_topic: msg.topic,
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-validation'
  };
  msg.invalid = true;
  return [null, msg];
}
msg.invalid = false;
return [msg, null];

const p = msg.payload;
const topic = msg.topic || '';
const expectedPrefix = 'iot/telemetry/';
const known = {
  'TEMP-001': 'iot/telemetry/temperature/TEMP-001',
  'HUM-001': 'iot/telemetry/humidity/HUM-001',
  'MOTION-001': 'iot/telemetry/motion/MOTION-001',
  'DOOR-001': 'iot/telemetry/door/DOOR-001',
  'CAM-001': 'iot/telemetry/camera/CAM-001',
  'LIGHT-001': 'iot/telemetry/light/LIGHT-001'
};
// Topic abuse detection for known devices writing wrong topic
if (known[p.device_id] && topic !== known[p.device_id] && !topic.startsWith(expectedPrefix + p.device_type)) {
  msg.payload = {
    event_type: 'TOPIC_ABUSE',
    severity: 'HIGH',
    risk_score: 25,
    description: 'Device ' + p.device_id + ' published to unauthorized topic: ' + topic,
    device_id: p.device_id,
    mqtt_topic: topic,
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-validation'
  };
  return [null, msg];
}
return [msg, null];

const isolated = global.get('isolated_devices') || {};
const id = msg.payload.device_id;
if (isolated[id]) {
  msg.payload = {
    event_type: 'POST_ISOLATION_BLOCKED',
    severity: 'HIGH',
    risk_score: 0,
    description: 'Telemetry from ISOLATED device rejected: ' + id,
    device_id: id,
    mqtt_topic: msg.topic,
    action: 'REJECT',
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-isolation'
  };
  return [null, msg]; // blocked path
}
return [msg, null];

const known = ['TEMP-001','HUM-001','MOTION-001','DOOR-001','CAM-001','LIGHT-001'];
const id = msg.payload.device_id;
const registry = global.get('device_registry') || {};
const now = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');

if (!known.includes(id)) {
  msg.payload = {
    event_type: 'UNAUTHORIZED_DEVICE',
    severity: 'HIGH',
    risk_score: 20,
    description: 'Unknown device_id received: ' + id,
    device_id: id,
    mqtt_topic: msg.topic,
    timestamp: now,
    source: 'node-red-registry'
  };
  return [null, msg];
}

// Update registry in-memory
if (!registry[id]) {
  registry[id] = { device_id: id, device_type: msg.payload.device_type, status: 'ACTIVE', risk_score: 0, first_seen: now, last_seen: now };
} else {
  registry[id].last_seen = now;
}
global.set('device_registry', registry);
msg.registry = registry[id];
return [msg, null];

const id = msg.payload.device_id;
const now = Date.now();
const windowMs = 60000;
const maxPerMin = 30; // documented: baseline 1-5, anomaly when >> baseline

let rates = context.get('rates') || {};
if (!rates[id]) rates[id] = [];
rates[id].push(now);
rates[id] = rates[id].filter(t => now - t < windowMs);
// Bound memory
if (rates[id].length > 500) rates[id] = rates[id].slice(-200);
context.set('rates', rates);

if (rates[id].length > maxPerMin) {
  msg.payload = {
    event_type: 'MESSAGE_RATE_ANOMALY',
    severity: 'HIGH',
    risk_score: 25,
    description: 'Message rate exceeded device baseline for ' + id + ' (' + rates[id].length + ' in 60s, threshold ' + maxPerMin + ')',
    device_id: id,
    mqtt_topic: msg.topic,
    observed_value: rates[id].length,
    expected_value: maxPerMin,
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-behavior'
  };
  return [null, msg];
}
return [msg, null];

const p = msg.payload;
const id = p.device_id;
let anomaly = false;
let expected = '';

if (id === 'TEMP-001' && typeof p.value === 'number' && p.value > 50) {
  anomaly = true; expected = '<= 50 C (project anomaly threshold)';
}
if (id === 'HUM-001' && typeof p.value === 'number' && p.value > 95) {
  anomaly = true; expected = '<= 95 % (project anomaly threshold)';
}

if (anomaly) {
  msg.payload = {
    event_type: 'SENSOR_VALUE_ANOMALY',
    severity: 'MEDIUM',
    risk_score: 15,
    description: 'Abnormal sensor value for ' + id,
    device_id: id,
    mqtt_topic: msg.topic,
    observed_value: p.value,
    expected_value: expected,
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-behavior'
  };
  return [null, msg];
}
return [msg, null];

const e = msg.payload;
e.event_id = e.event_id || ('EVT-' + Math.random().toString(16).slice(2, 10).toUpperCase());
e.source = e.source || 'node-red-detection-engine';
e.status = e.status || 'OPEN';
e.timestamp = e.timestamp || new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
msg.payload = e;
return msg;

const e = msg.payload;
const windowMs = 60000;
const now = Date.now();
let recent = context.get('recent_events') || [];
recent.push({ ...e, _ts: now });
recent = recent.filter(x => now - x._ts < windowMs);
if (recent.length > 100) recent = recent.slice(-50);
context.set('recent_events', recent);

// Correlate if >= 3 different event types for same device in window
const sameDev = recent.filter(x => x.device_id === e.device_id);
const types = [...new Set(sameDev.map(x => x.event_type))];
if (types.length >= 3) {
  const corrId = 'CORR-' + Math.random().toString(16).slice(2, 8).toUpperCase();
  const related = sameDev.map(x => x.event_id).filter(Boolean);
  msg.payload = {
    event_type: 'CORRELATED_SECURITY_INCIDENT',
    severity: 'CRITICAL',
    risk_score: 40,
    description: 'Correlated incident for ' + e.device_id + ': ' + types.join(', '),
    device_id: e.device_id,
    correlation_id: corrId,
    related_event_ids: related.join(','),
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-correlation',
    status: 'OPEN'
  };
  // Pass both original and correlated — we forward correlated as primary enrichment flag
  msg.correlated = true;
}
return msg;

const contrib = {
  'UNAUTHORIZED_DEVICE': 20,
  'AUTHENTICATION_ANOMALY': 15,
  'MESSAGE_RATE_ANOMALY': 25,
  'TOPIC_ABUSE': 25,
  'SENSOR_VALUE_ANOMALY': 15,
  'DEVICE_SPOOFING': 30,
  'SCHEMA_VALIDATION_FAILURE': 10,
  'CORRELATED_SECURITY_INCIDENT': 40,
  'POST_ISOLATION_BLOCKED': 0
};
const e = msg.payload;
const add = contrib[e.event_type] !== undefined ? contrib[e.event_type] : (e.risk_score || 10);
const id = e.device_id || 'unknown';

// Prevent rapid double-count of identical type within short window
let last = context.get('last_contrib') || {};
const key = id + ':' + e.event_type;
const now = Date.now();
if (last[key] && (now - last[key]) < 5000 && e.event_type !== 'CORRELATED_SECURITY_INCIDENT') {
  // skip additive for same type within 5s
} else {
  let scores = global.get('device_scores') || {};
  scores[id] = Math.min(100, (scores[id] || 0) + add);
  global.set('device_scores', scores);
  last[key] = now;
  context.set('last_contrib', last);
}

const scores = global.get('device_scores') || {};
e.risk_score = scores[id] || add;
if (e.risk_score >= 80) e.severity = 'CRITICAL';
else if (e.risk_score >= 60) e.severity = 'HIGH';
else if (e.risk_score >= 30) e.severity = 'MEDIUM';
else e.severity = 'LOW';

msg.payload = e;
msg.device_risk = e.risk_score;
return msg;

const e = msg.payload;
const score = e.risk_score || 0;
let action = 'LOG';

if (score >= 80) {
  action = 'ISOLATE';
  e.severity = 'CRITICAL';
  // Logical isolation
  let isolated = global.get('isolated_devices') || {};
  isolated[e.device_id] = { reason: e.event_type, risk: score, ts: e.timestamp, event_id: e.event_id };
  global.set('isolated_devices', isolated);
  // Update registry status
  let reg = global.get('device_registry') || {};
  if (reg[e.device_id]) reg[e.device_id].status = 'ISOLATED';
  if (reg[e.device_id]) reg[e.device_id].risk_score = score;
  global.set('device_registry', reg);
  // Create incident
  let incidents = global.get('incidents') || [];
  const inc = {
    incident_id: 'INC-' + Math.random().toString(16).slice(2, 6).toUpperCase(),
    device_id: e.device_id,
    attack_type: e.event_type,
    risk_score: score,
    action: 'ISOLATED',
    status: 'CONTAINED',
    created_at: e.timestamp,
    correlation_id: e.correlation_id || null
  };
  incidents.push(inc);
  if (incidents.length > 200) incidents = incidents.slice(-100);
  global.set('incidents', incidents);
  e.incident_id = inc.incident_id;
} else if (score >= 60) {
  action = 'ALERT_ENHANCED_MONITORING';
  let reg = global.get('device_registry') || {};
  if (reg[e.device_id]) reg[e.device_id].status = 'SUSPICIOUS';
  global.set('device_registry', reg);
} else if (score >= 30) {
  action = 'WARNING';
}

e.action = action;

// Store event in global list for dashboard
let events = global.get('security_events') || [];
events.push(e);
if (events.length > 500) events = events.slice(-300);
global.set('security_events', events);

msg.payload = e;
return msg;

const reg = global.get('device_registry') || {};
const isolated = global.get('isolated_devices') || {};
const events = global.get('security_events') || [];
const incidents = global.get('incidents') || [];
const scores = global.get('device_scores') || {};

const devices = Object.keys(reg).length ? Object.values(reg) : [
  {device_id:'TEMP-001',device_type:'temperature',status:'ACTIVE',risk_score:0,last_seen:'—'},
  {device_id:'HUM-001',device_type:'humidity',status:'ACTIVE',risk_score:0,last_seen:'—'},
  {device_id:'MOTION-001',device_type:'motion',status:'ACTIVE',risk_score:0,last_seen:'—'},
  {device_id:'DOOR-001',device_type:'door',status:'ACTIVE',risk_score:0,last_seen:'—'},
  {device_id:'CAM-001',device_type:'camera',status:'ACTIVE',risk_score:0,last_seen:'—'},
  {device_id:'LIGHT-001',device_type:'light',status:'ACTIVE',risk_score:0,last_seen:'—'}
];
// apply isolation status
Object.keys(isolated).forEach(id => {
  const d = devices.find(x => x.device_id === id);
  if (d) { d.status = 'ISOLATED'; d.risk_score = isolated[id].risk || d.risk_score; }
});
devices.forEach(d => { if (scores[d.device_id] !== undefined) d.risk_score = scores[d.device_id]; });

const total = 6;
const active = devices.filter(d => d.status === 'ACTIVE').length;
const suspicious = devices.filter(d => d.status === 'SUSPICIOUS').length;
const isolCount = Object.keys(isolated).length;
const critical = events.filter(e => e.severity === 'CRITICAL').length;
const openInc = incidents.filter(i => i.status !== 'RESOLVED').length;

msg.stats = { total, active, suspicious, isolated: isolCount, events: events.length, critical, openInc };
msg.devices = devices;
msg.events = events.slice(-50).reverse();
msg.incidents = incidents.slice(-20).reverse();
msg.recentEvents = msg.events;

const riskBuckets = [0,0,0,0];
events.forEach(e => {
  const r = e.risk_score || 0;
  if (r >= 80) riskBuckets[3]++;
  else if (r >= 60) riskBuckets[2]++;
  else if (r >= 30) riskBuckets[1]++;
  else riskBuckets[0]++;
});
msg.riskBuckets = riskBuckets;

const typeCounts = {};
events.forEach(e => { typeCounts[e.event_type] = (typeCounts[e.event_type]||0)+1; });
msg.threatTypes = Object.entries(typeCounts).map(([t,c]) => ({type:t, count:c}));

return msg;

const cmd = msg.payload;
let isolated = global.get('isolated_devices') || {};
let reg = global.get('device_registry') || {};
let scores = global.get('device_scores') || {};

if (cmd === 'list') {
  msg.payload = { isolated, registry: reg, scores };
  return msg;
}

// Recover: msg.payload = { action: 'recover', device_id: 'TEMP-001' }
if (cmd && cmd.action === 'recover' && cmd.device_id) {
  const id = cmd.device_id;
  delete isolated[id];
  if (reg[id]) reg[id].status = 'ACTIVE';
  scores[id] = 0;
  global.set('isolated_devices', isolated);
  global.set('device_registry', reg);
  global.set('device_scores', scores);
  msg.payload = {
    event_type: 'DEVICE_RECOVERED',
    severity: 'LOW',
    risk_score: 0,
    description: 'Device recovered from ISOLATED to ACTIVE: ' + id,
    device_id: id,
    action: 'RECOVER',
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-admin',
    status: 'RESOLVED'
  };
  // also push to events
  let events = global.get('security_events') || [];
  events.push(msg.payload);
  global.set('security_events', events);
  return msg;
}
msg.payload = { error: 'unknown command' };
return msg;

const id = msg.payload.device_id;
const inst = msg.payload.client_instance || 'default';
let map = context.get('client_instances') || {};
const prev = map[id];
map[id] = inst;
context.set('client_instances', map);
if (prev && prev !== inst) {
  msg.payload = {
    event_type: 'DEVICE_SPOOFING',
    severity: 'CRITICAL',
    risk_score: 30,
    description: 'Device ' + id + ' published from a different client instance (' + prev + ' → ' + inst + ')',
    device_id: id,
    observed_value: inst,
    expected_value: prev,
    mqtt_topic: msg.topic,
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    source: 'node-red-behavior'
  };
  return [null, msg];
}
return [msg, null];

// Durable append-only log under /data/database (mounted).
// Full SQLite INSERT nodes: install node-red-node-sqlite and wire using schema.sql.
const fs = global.get('fs') || require('fs');
const path = '/data/database/events.jsonl';
try {
  fs.appendFileSync(path, JSON.stringify(msg.payload) + '\n');
} catch (e) {
  node.warn('persist event: ' + e.message);
}
return msg;

const fs = global.get('fs') || require('fs');
const path = '/data/database/telemetry.jsonl';
try {
  fs.appendFileSync(path, JSON.stringify(msg.payload) + '\n');
} catch (e) {
  node.warn('persist telemetry: ' + e.message);
}
return msg;
